def solve(inputs: dict) -> float:
    X = inputs.get('initial_value', 329209103)
    num_steps = inputs.get('num_steps', 21)

    # Keep X within 32 bits using a mask
    mask = (1 << 32) - 1

    for _ in range(num_steps):
        X ^= (X << 13) & mask
        X ^= (X >> 9) & mask
        X ^= (X << 17) & mask
        X &= mask

    return float(X)
